  'des.choix.subtitle': { fr: "Vous hésitez entre deux chemins ? Comparez l'énergie de chaque option.", en: "Hesitating between two paths? Compare the energy of each option.", es: "¿Duda entre dos caminos? Compare la energía de cada opción.", hi: "दो पथ में संकोच है? प्रत्येक विकल्प की ऊर्जा तुलना करें।" },
