  'des.choix.noteA': { fr: "Notez la vibration (ex : Lune en Cancer en Maison 4 = introspection, confort, protection du foyer).", en: "Note the vibration (e.g. Moon in Cancer in House 4 = introspection, comfort, home protection).", es: "Anote la vibración (ej.: Luna en Cáncer en Casa 4 = introspección, confort, protección del hogar).", hi: "कंपन दर्ज करें (उदा: चंद्र कर्क में भाव 4 = अंतर्मुखता, सुख, गृह-रक्षा)।" },
  'des.choix.noteB': { fr: "Notez la vibration (ex : Uranus en Verseau en Maison 10 = grand changement pro, liberté, rupture de routine).", en: "Note the vibration (e.g. Uranus in Aquarius in House 10 = big career shift, freedom, break from routine).", es: "Anote la vibración (ej.: Urano en Acuario en Casa 10 = gran cambio profesional, libertad, ruptura de la rutina).", hi: "कंपन दर्ज करें (जैसे: कुंभ में यूरेनस, दशम भाव में = बड़ा व्यावसायिक बदलाव, मुक्ति, दिनचर्या भंग)।" },
  'des.choix.reflect': { fr: "Comparez la fluidité des énergies. Le Premier Choix apporte-t-il de la stabilité ou de la stagnation ? Le Second Choix génère-t-il du renouveau ou de l'instabilité ?", en: "Compare the fluidity of energies. Does the First Choice bring stability or stagnation? Does the Second Choice spark renewal or instability?", es: "Compare la fluidez de las energías. ¿La Primera Elección aporta estabilidad o estancamiento? ¿La Segunda Elección genera renovación o inestabilidad?", hi: "ऊर्जाओं की प्रवाहता तुलें। क्या प्रथम चयन स्थिरता लाता है या जड़ता? क्या द्वितीय चयन नयापन देता है या अस्थिरता?" },
  'des.choix.analysis': { fr: "Analyse du tirage", en: "Cast Analysis", es: "Análisis de la tirada", hi: "भविष्यकथन का विश्लेषण" },
  'des.choix.analysisFirst': { fr: "Analyse du 1er tirage", en: "First Cast Analysis", es: "Análisis de la 1.ª tirada", hi: "प्रथम भविष्यकथन का विश्लेषण" },
  'des.choix.analysisSecond': { fr: "Analyse du 2nd tirage", en: "Second Cast Analysis", es: "Análisis de la 2.ª tirada", hi: "द्वितीय भविष्यकथन का विश्लेषण" },
  'des.choix.searching': { fr: "Recherche de l'interprétation…", en: "Searching interpretation…", es: "Buscando la interpretación…", hi: "व्याख्या खोजी जा रही है…" },
