  'des.choix.instructFirst': { fr: "Concentrez-vous sur votre <b>première option</b> (ex: « changer d'emploi »).", en: "Focus on your <b>first option</b> (e.g. « change jobs »).", es: "Concéntrese en su <b>primera opción</b> (ej.: « cambiar de trabajo »).", hi: "अपने <b>पहले विकल्प</b> पर ध्यान केंद्रित करें (जैसे: « नौकरी बदलना »)।" },
